-- 묻고 답하기 씨앗 질문 30개 — 생성물(node tools/build-qa-seeds-sql.mjs). 손으로 고치지 말고 docs/qa-seeds.json 을 고친다.
-- Supabase 대시보드 → SQL Editor 에 **전부** 붙여 넣고 Run. db/add_community.sql 을 먼저 돌려 둔 뒤에.
-- 여러 번 돌려도 괜찮다 — 같은 제목의 질문이 이미 있으면 건너뛴다. 운영자 메일로 사이트에 한 번 로그인해 둔 계정이 글 주인이 된다.
-- 맨 끝 select 가 「질문 30 · 답 30」 이상이면 잘 들어간 것이다.
begin;
alter table qa_questions disable trigger qa_limit;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'-아서/어서 and -(으)니까 — what\'s the difference?', E'Both mean \'because\', right? 늦어서 미안해요 is OK, but 늦으니까 미안해요 sounds strange to my Korean friend. Why?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'-아서/어서 and -(으)니까 — what\'s the difference?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'둘 다 「이유」를 말하지만 쓰임이 달라요.\n\n① -아서/어서: 자연스러운 까닭을 말해요. 뒤에 명령이나 권유(-세요, -(으)ㅂ시다)가 올 수 없고, 사과나 감사 인사에 잘 어울려요.\n  · 늦어서 미안해요.\n  · 도와주셔서 고마워요.\n② -(으)니까: 말하는 사람이 생각하는 주관적인 까닭이에요. 뒤에 명령이나 권유가 와도 자연스러워요.\n  · 비가 오니까 우산을 가져가세요.\n  · 날씨가 좋으니까 공원에 갈까요?\n\nBoth express a reason, but they are used differently. -아서/어서 introduces a natural cause or result and cannot be followed by commands or suggestions, making it ideal for apologies and thank-yous. In contrast, -(으)니까 expresses the speaker\'s own reason or discovery, so commands and suggestions naturally follow.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'은/는 하고 이/가 차이가 아직도 헷갈려요', E'한국어 공부한 지 반년 넘었는데 은/는과 이/가를 언제 써야 하는지 아직 잘 모르겠어요. 쉬운 구별법이 있을까요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'은/는 하고 이/가 차이가 아직도 헷갈려요') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'은/는은 「화제나 대조」, 이/가는 「새로운 정보나 주어」를 강조할 때 써요.\n\n① 은/는: 이미 알고 있는 대상을 꺼내거나, 다른 것과 비교할 때 써요.\n  · 저는 사과는 좋아해요. 하지만 바나나는 싫어해요.\n  · 오늘은 날씨가 참 좋아요.\n② 이/가: 눈앞의 상황을 처음 말하거나, \'누가\' 했는지 콕 집어 말할 때 써요.\n  · 밖을 봐요. 눈이 와요!\n  · 누가 이 책을 읽었어요? / 동생이 읽었어요.\n\n은/는 is used for topic marking or contrast (talking about an already known topic or comparing two things). 이/가 focuses on the specific subject itself or introduces new information.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'When do I use -고 있다 vs -아/어 있다?', E'I learned that both express ongoing states or actions. Can I say 의자에 앉고 있어요 to mean I am sitting on a chair?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'When do I use -고 있다 vs -아/어 있다?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'진행 중인 \'행동\'과 이미 끝난 뒤 유지되는 \'상태\'가 달라요.\n\n① -고 있다: 지금 어떤 행동을 직접 하고 있는 중이에요.\n  · 지금 책을 읽고 있어요.\n  · 친구가 밥을 먹고 있어요.\n② -아/어 있다: 행동이 끝나고 그 결과 상태가 계속 남아 있는 모습이에요.\n  · 동생이 의자에 앉아 있어요.\n  · 꽃이 예쁘게 피어 있어요.\n따라서 의자에 앉는 동작 중이 아니라면 「앉아 있어요」가 맞아요.\n\n-고 있다 indicates an action currently in progress (reading, eating). -아/어 있다 indicates a lingering state after an action is completed, usually with intransitive verbs like sitting or standing. Say 앉아 있어요 for \'sitting on a chair\'.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'「갈게요」랑 「갈 거예요」는 언제 달라요?', E'둘 다 미래를 말하는 것 같은데, 친구한테 헤어질 때 \'저 갈게요\'라고 하는 이유가 궁금해요. \'갈 거예요\'라고 하면 안 되나요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'「갈게요」랑 「갈 거예요」는 언제 달라요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'상대방과의 약속이나 의지인지, 단순한 계획인지에 따라 달라요.\n\n① -(으)ㄹ게요: 듣는 사람과의 관계에서 내 의지나 약속을 표현해요. 듣는 사람에게 영향을 미치는 결정을 그 자리에서 말할 때 써요.\n  · 먼저 갈게요. 내일 봐요!\n  · 제가 커피를 살게요.\n② -(으)ㄹ 거예요: 이미 정해 둔 계획이나 단순한 미래 추측을 말해요.\n  · 저는 내일 부산에 갈 거예요.\n  · 오후에는 비가 올 거예요.\n\n-(으)ㄹ게요 expresses a spontaneous decision, promise, or intention directed at the listener. -(으)ㄹ 거예요 expresses a general future plan or prediction.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'Difference between -지만 and -는데?', E'I often see both translated as \'but\'. Are they completely interchangeable in every sentence?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'Difference between -지만 and -는데?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'두 표현 모두 앞뒤 내용을 잇지만 느낌이 달라요.\n\n① -지만: 앞 내용과 뒷 내용이 정반대임을 분명하게 대비할 때 써요.\n  · 한국어는 어렵지만 재미있어요.\n  · 값은 비싸지만 맛이 좋아요.\n② -는데: 반대되는 뜻뿐만 아니라, 뒤에 이어질 말의 배경이나 상황을 미리 깔아 줄 때도 널리 써요.\n  · 지금 비가 오는데 우산이 있어요?\n  · 어제 친구를 만났는데 참 반가웠어요.\n\n-지만 is used for a direct, clear contrast (A is true, but B is the opposite). -는데 is much broader: it provides background context or circumstance for the following clause, which may or may not be contrasting.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'-(으)세요 하고 -(으)십시오 는 어떻게 다른가요?', E'둘 다 존댓말로 명령하는 말인데 식당이나 방송에서는 왜 서로 다르게 쓰는지 궁금해요. 일상 대화에서는 무엇을 써야 하나요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'-(으)세요 하고 -(으)십시오 는 어떻게 다른가요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'격식의 높낮이와 말하는 상황이 달라요.\n\n① -(으)세요: 일상 대화에서 가장 널리 쓰는 부드러운 존댓말(해요체)이에요.\n  · 여기에 이름을 쓰세요.\n  · 맛있게 드세요.\n② -(으)십시오: 공식적인 행사, 공공장소의 안내 방송, 격식 있는 자리(하십시오체)에서 정중하게 요청할 때 써요.\n  · 자리에 앉아 주십시오.\n  · 문이 닫히니 뒤로 물러서십시오.\n일상 대화에서는 「-(으)세요」를 쓰면 충분해요.\n\n-(으)세요 is polite and friendly, used in everyday conversations. -(으)십시오 is formal and highly polite, commonly seen in public announcements, official notices, and business settings.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'How do I say \'have you tried\' vs \'have you ever\' in Korean?', E'I want to ask a friend if they have eaten bibimbap before. Should I use -아/어 보다 or -(으)ㄴ 적이 있다?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'How do I say \'have you tried\' vs \'have you ever\' in Korean?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'새로운 시도를 해 보았는지, 과거의 경험 자체가 있는지에 따라 표현이 달라요.\n\n① -아/어 보다: 어떤 일이나 행동을 시도해 본다는 뜻이에요.\n  · 비빔밥을 한번 먹어 보세요.\n  · 한국에 가 보고 싶어요.\n② -(으)ㄴ 적이 있다: 과거에 그런 일을 겪은 경험이 있다는 뜻이에요.\n  · 비빔밥을 먹은 적이 있어요?\n  · 저는 제주도에 간 적이 없어요.\n두 문법을 합쳐서 「비빔밥을 먹어 본 적이 있어요?」(경험 삼아 시도해 본 적이 있냐)라고 가장 많이 물어봐요.\n\n-아/어 보다 means to try doing something. -(으)ㄴ 적이 있다 means to have the experience of doing something in the past. To ask \'Have you ever tried eating...?\', combine them into -아/어 본 적이 있어요?.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'「-(으)려고 해요」와 「-(으)ㄹ 생각이에요」는 느낌이 다른가요?', E'둘 다 앞으로 할 일을 말할 때 쓰는 것 같은데 어떤 차이가 있는지 궁금합니다.' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'「-(으)려고 해요」와 「-(으)ㄹ 생각이에요」는 느낌이 다른가요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'행동을 실행하려는 준비 단계와 마음에 품은 계획이라는 점에서 조금 달라요.\n\n① -(으)려고 하다: 구체적인 행동을 하려는 적극적인 의도나 목적을 나타내요.\n  · 주말에 도서관에 가려고 해요.\n  · 새 옷을 한 벌 사려고 해요.\n② -(으)ㄹ 생각이다: 마음속으로 그렇게 할까 하고 생각 중인 계획이나 고민을 부드럽게 표현해요.\n  · 내년에 한국에 유학을 갈 생각이에요.\n  · 이번 주말에는 집에서 쉴 생각이에요.\n\n-(으)려고 하다 indicates an active intention or preparation to perform a specific action soon. -(으)ㄹ 생각이다 gently conveys a thought, contemplation, or tentative future plan in your mind.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'Is there any difference between 안 and -지 않다?', E'In beginner lessons I learned 안 먹어요, but in books I often see 먹지 않아요. Are they identical in meaning?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'Is there any difference between 안 and -지 않다?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'뜻은 같지만 말하는 상황과 격식이 달라요.\n\n① 안: 말할 때(구어) 가장 편하고 자주 쓰는 짧은 부정 표현이에요.\n  · 저는 아침을 안 먹었어요.\n  · 오늘은 날씨가 안 추워요.\n② -지 않다: 글(문어)이나 공식적인 자리에서 주로 쓰는 긴 부정 표현이에요.\n  · 주말에는 가게 문을 열지 않습니다.\n  · 그 소식은 사실과 다르지 않습니다.\n일상 회화에서는 동사나 형용사 앞에 「안」을 붙이는 것이 자연스러워요.\n\nBoth mean \'not\' and negate the predicate. 안 is short negation, predominant in casual and everyday spoken Korean. -지 않다 is long negation, commonly preferred in formal speech, writing, and literature.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'grammar', E'「밥 먹으러 가요」와 「밥 먹으려고 가요」 차이가 궁금해요', E'이동할 때 목적을 나타내는 문법이 두 개 있어서 헷갈려요. 가다/오다 앞에는 항상 -(으)러를 써야 하나요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'「밥 먹으러 가요」와 「밥 먹으려고 가요」 차이가 궁금해요') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'가다, 오다, 다니다 같은 이동 동사 앞에는 주로 「-(으)러」를 써요.\n\n① -(으)러: \'가다/오다\'와 같은 이동 목적만을 나타내는 전용 표현이에요.\n  · 친구를 만나러 카페에 가요.\n  · 한국어를 배우러 학원에 다녀요.\n② -(으)려고: 일반적인 행동의 목적이나 의도를 나타내며 뒤에 다양한 동사가 와요.\n  · 시험에 합격하려고 열심히 공부해요.\n  · 책을 읽으려고 안경을 썼어요.\n이동 동사(가다, 오다) 뒤에서는 「-(으)러 가다」가 훨씬 자연스러워요.\n\n-(으)러 is specifically paired with movement verbs like 가다 (go) or 오다 (come) to express the purpose of moving. -(으)려고 is a general intention marker used with many other action verbs.\n\n치즈감자 「문법」에서 이 표현을 찾으면 예문과 블록 맞추기 · 바꿔 쓰기로 연습할 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'words', E'How should I answer when someone asks \'알아요?\' (알겠어요 vs 알았어요)', E'My teacher asked if I understood the homework. Should I answer \'네, 알겠어요\' or \'네, 알았어요\'? And what if I don\'t know?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'How should I answer when someone asks \'알아요?\' (알겠어요 vs 알았어요)') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'상황과 듣는 사람에 따라 자연스러운 대답이 달라요.\n\n① 네, 알겠습니다 / 알겠어요: 상대방의 설명, 지시, 부탁을 듣고 \'앞으로 그렇게 하겠다\'고 받아들일 때 써요.\n  · 선생님의 지시를 들었을 때: 네, 알겠습니다!\n② 네, 알았어요: 친구나 손아래 사람의 말을 가볍게 알아들었을 때 써요.\n  · 친구의 부탁을 들었을 때: 응, 알았어. 이따가 전화할게.\n③ 잘 모르겠습니다 / 몰라요: 정보를 모를 때는 「알지 못해요」가 아니라 「모르다」를 써요.\n  · 질문의 답을 잘 모르겠어요.\n\nUse 알겠습니다 / 알겠어요 to acknowledge instructions, rules, or requests politely. Use 알았어요 for casual agreements with close peers. When you lack information or do not know the answer, use 몰라요 or 잘 모르겠습니다.\n\n치즈감자 「사전」에서 「알다」 · 「모르다」의 예문을 더 볼 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'words', E'「보다」, 「구경하다」, 「관람하다」는 어떻게 구별해요?', E'시장에 가거나 미술관에 갈 때 한국 친구들이 구경한다, 관람한다고 다르게 말해요. 세 단어는 어떻게 다른가요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'「보다」, 「구경하다」, 「관람하다」는 어떻게 구별해요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'대상을 바라보는 목적과 장소의 격식이 달라요.\n\n① 보다: 눈으로 무언가를 보는 가장 기본적이고 넓은 단어예요.\n  · 주말에 집에서 영화를 보았어요.\n② 구경하다: 시장, 축제, 거리 등을 흥미롭게 둘러보며 즐길 때 써요.\n  · 친구들과 시장을 구경했어요.\n③ 관람하다: 공연, 전시회, 박물관, 스포츠 경기 등을 격식을 갖추어 관객으로서 볼 때 써요.\n  · 미술관에서 그림을 관람했어요.\n\n보다 is the basic verb \'to see/watch\'. 구경하다 means to sightsee, browse, or casually look around market stalls or festivals. 관람하다 is a formal verb for viewing exhibitions, plays, or sports events as a spectator.\n\n치즈감자 「단어」에서 이 낱말들을 소리와 예문으로 익혀 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'words', E'What is the difference between 아까 and 이따가?', E'Both seem to refer to short periods of time on the same day. How do I know which one to choose?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'What is the difference between 아까 and 이따가?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'오늘 하루 안에서 \'과거\'인지 \'미래\'인지가 달라요.\n\n① 아까: 지금보다 조금 전, 오늘 지나간 가까운 과거예요.\n  · 아까 커피를 한 잔 마셨어요.\n  · 아까 온 사람이 누구예요?\n② 이따가: 지금보다 조금 뒤, 오늘 앞으로 다가올 가까운 미래예요.\n  · 이따가 점심시간에 다시 만나요.\n  · 바쁘니까 이따가 전화할게요.\n\n아까 refers to a little while ago earlier today (past). 이따가 refers to a little later today (future). Remember: 아까 looks back, 이따가 looks forward.\n\n치즈감자 「단어」에서 이 낱말들을 소리와 예문으로 익혀 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'words', E'「괜찮아요」는 언제 거절하는 뜻이 되나요?', E'친구가 물을 더 마실 거냐고 물어봤을 때 \'괜찮아요\'라고 대답했어요. \'좋다\'는 뜻인가요, 아니면 \'거절\'인가요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'「괜찮아요」는 언제 거절하는 뜻이 되나요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'말투와 손짓, 문맥에 따라 뜻이 완전히 달라져요.\n\n① 거절(사양): 권유나 호의를 받을 때 손을 가볍게 흔들며 말하면 \'필요 없다(No, thank you)\'는 뜻이에요.\n  · 커피 더 드릴까요? / 아니요, 괜찮아요.\n  · 짐을 들어 드릴까요? / 혼자 들 수 있어서 괜찮아요.\n② 허락 · 안심: 문제나 걱정이 없을 때 \'아무렇지 않다(I\'m fine / It\'s okay)\'는 뜻이에요.\n  · 넘어져서 아파요? / 아니요, 정말 괜찮아요.\n  · 오늘 조금 늦어도 괜찮아요.\n상대가 무언가를 권할 때 「괜찮아요」라고 하면 대부분 거절의 뜻으로 받아들여요.\n\n괜찮아요 can mean \'I am fine\' or \'No, thank you\' depending on context. When someone offers food or help, answering 괜찮아요 usually politely declines the offer.\n\n치즈감자 「단어」에서 이 낱말들을 소리와 예문으로 익혀 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'words', E'When can I say \'수고하세요\'? Can I say it to my teacher?', E'I heard Koreans say 수고하세요 when leaving a shop or taxi. Can I say this to my university professor or boss?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'When can I say \'수고하세요\'? Can I say it to my teacher?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'윗사람에게는 쓰지 않는 것이 좋아요.\n\n① 수고하세요: 주로 동료, 손아래 사람, 또는 상점이나 택시에서 일하는 분에게 감사를 표하며 떠날 때 써요.\n  · 택시에서 내릴 때: 감사합니다, 기사님 수고하세요.\n  · 일을 계속하는 동료에게 먼저 나가면서: 먼저 갈게요. 수고하세요.\n② 윗사람에게: 선생님이나 직장 상사에게는 「감사합니다」 또는 「안녕히 계세요」라고 인사해야 해요.\n  · 수업이 끝난 후 선생님께: 교수님, 감사합니다. 안녕히 계세요.\n  · 퇴근할 때 상사에게: 팀장님, 먼저 들어가 보겠습니다.\n\'수고\'라는 말 자체가 고생을 뜻하므로 윗사람에게 건네면 결례가 될 수 있어요.\n\n수고하세요 means \'keep up the good work\'. You can say it to store clerks, taxi drivers, or peers, but it is best avoided with professors or managers. To elders, use 감사합니다 or 안녕히 계세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'words', E'「다르다」와 「틀리다」가 자주 헷갈려요', E'한국 사람들이 말할 때 \'생각이 틀려요\'라고 하는 걸 들었는데 사전에는 다르다고 나와요. 무엇이 맞는 말인가요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'「다르다」와 「틀리다」가 자주 헷갈려요') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'성질이 같지 않은 것과 정답에서 어긋난 것은 구별해야 맞아요.\n\n① 다르다: 서로 같지 않고 차이가 있다는 뜻이에요 (Different).\n  · 제 동생은 저와 성격이 달라요.\n  · 나라마다 문화가 달라요.\n② 틀리다: 계산이나 답이 옳지 않고 어긋났다는 뜻이에요 (Wrong / Incorrect).\n  · 시험 문제의 정답이 틀렸어요.\n  · 계산을 잘못해서 답이 틀렸어요.\n많은 한국인이 일상에서 \'다르다\' 자리에 \'틀리다\'를 섞어 쓰지만, 바른 한국어는 서로 다른 것에 「다르다」를 써요.\n\n다르다 means \'different\' (not the same). 틀리다 means \'wrong\' (incorrect). While many native speakers casually misuse 틀리다 to mean different, standard Korean distinguishes them clearly.\n\n치즈감자 「단어」에서 이 낱말들을 소리와 예문으로 익혀 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'words', E'Difference between 끝나다 and 마치다?', E'I know both mean \'to end\' or \'finish\'. Can I say 수업을 끝났어요 or should I say 수업이 끝났어요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'Difference between 끝나다 and 마치다?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'주어와 목적어의 쓰임, 즉 자동사와 타동사의 차이예요.\n\n① 끝나다: 어떤 일이나 상황이 스스로 끝나는 자동사예요. 앞에는 「이/가」가 와요.\n  · 드디어 수업이 끝났어요.\n  · 영화가 몇 시에 끝나요?\n② 마치다: 사람이 의지를 가지고 어떤 일을 마무리 짓는 타동사예요. 앞에는 「을/를」이 와요.\n  · 학생들이 숙제를 마쳤어요.\n  · 회의를 일찍 마치고 퇴근했어요.\n따라서 「수업이 끝났어요」 또는 「수업을 마쳤어요」로 써야 올바릅니다.\n\n끝나다 is an intransitive verb (something ends on its own), taking subject marker 이/가. 마치다 is a transitive verb (someone finishes something), taking object marker 을/를. Say 수업이 끝났어요 or 수업을 마쳤어요.\n\n치즈감자 「단어」에서 이 낱말들을 소리와 예문으로 익혀 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'topik', E'TOPIK II 쓰기 53번 그래프 글은 어떻게 문단을 나누나요?', E'53번 문항에서 200~300자 짧은 글을 쓸 때 문단을 나누어야 하나요? 어떤 순서로 쓰는 것이 좋은가요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'TOPIK II 쓰기 53번 그래프 글은 어떻게 문단을 나누나요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'보통 한 문단이나 두 문단으로 깔끔하게 구성해요.\n\n① 도입 (조사 주제 소개): 첫 문장에서 무엇에 대한 조사인지 밝혀요.\n  · 최근 한 조사에 따르면 성인의 독서량이 크게 변화한 것으로 나타났다.\n② 전개 (수치와 순위 분석): 그래프의 시작 수치와 변화 폭을 비교해요.\n  · 독서 인구 비율은 과거에 비해 지속적으로 증가하였다.\n③ 마무리 (원인과 전망): 자료에 제시된 원인과 앞으로의 기대를 적어요.\n  · 이러한 변화의 원인은 전자책 보급 확대로 보인다.\n제시된 정보만 간결하게 쓰고, 글쓴이 개인의 주관적인 생각은 넣지 않는 것이 고득점 비결이에요.\n\nFor Question 53, structure your 200-300 character answer into clear steps: introduce the survey topic, describe the key data changes and trends, and summarize the underlying reasons. Stick strictly to the provided information without adding personal opinions.\n\n치즈감자 「TOPIK」 쓰기에서 53번 유형을 모범답안과 함께 연습해 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'topik', E'How should I plan my outline for TOPIK II Question 54 essay?', E'I always freeze when I see Question 54. How many minutes should I spend brainstorming, and how should I structure the essay?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'How should I plan my outline for TOPIK II Question 54 essay?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'시험 시작 후 5~7분 동안 개요를 메모하는 것이 글쓰기를 완성하는 지름길이에요.\n\n① 개요 짜기 (5~7분): 문제에서 묻는 세 가지 질문에 대한 답변 핵심어를 1~2개씩 적어요.\n② 문단 구성 (3~4개 문단): 서론에서 주제의 배경을 밝히고, 본론에서 두 가지 질문의 근거를 다루며, 결론에서 종합 전망을 제시해요.\n  · 예시 도입 문장: 현대 사회에서는 개인의 노력이 무엇보다 중요하다.\n  · 예시 결론 문장: 따라서 제도적 지원과 성숙한 인식이 함께 뒷받침되어야 한다.\n\nSpend the first 5-7 minutes outlining key points for the three prompt questions. Divide your 600-700 character essay into 3-4 paragraphs: an introductory hook, two body paragraphs directly answering the prompts, and a concluding outlook.\n\n치즈감자 「TOPIK」 쓰기에서 54번 유형을 모범답안과 함께 연습해 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'topik', E'TOPIK 듣기 시험에서 한 문제를 놓쳤을 때는 어떻게 해야 하나요?', E'듣기를 풀다가 안 들리는 단어가 나와서 한참 고민하다가 다음 문제까지 다 놓쳤어요. 이럴 때 어떻게 대처해야 하나요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'TOPIK 듣기 시험에서 한 문제를 놓쳤을 때는 어떻게 해야 하나요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'지나간 문제는 과감하게 찍고 바로 다음 문제의 보기를 미리 읽어야 해요.\n\n① 바로 다음 문제로 넘어가기: 이미 지나간 문제는 다시 들을 수 없으므로 마음속으로 가장 가까운 답을 고르고 잊어버려요.\n  · 다음 문항의 질문과 보기를 먼저 훑어보면 들을 내용이 예측돼요.\n  · 듣기 지문이 나오기 전에 핵심 단어에 밑줄을 그어 두세요.\n② 한 대화로 두 문제를 푸는 문항: 듣기 전에 두 질문을 먼저 읽어 두고, 들으면서 두 문제의 답을 함께 찾아요.\n  · 한 문제는 중심 생각, 다른 문제는 세부 내용을 묻는 일이 많아요.\n  · 들은 내용과 보기가 맞는지 바로 표시해 두세요.\n\nIf you miss a listening question, make your best guess immediately and move on. Use the remaining audio silence to preview the questions and answer choices for the upcoming item. Never dwell on a missed question.\n\n치즈감자 「TOPIK」 듣기에서 문제를 풀어 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'topik', E'I always run out of time on the TOPIK reading section. Any tips?', E'When taking TOPIK II reading, I can never finish all 50 questions in 70 minutes. What strategies help manage time better?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'I always run out of time on the TOPIK reading section. Any tips?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'목표 점수에 맞춰 문제를 선택하고 푸는 순서를 전략적으로 짜야 해요.\n\n① 앞부분(1~20번)에서 시간을 아끼기: 문법과 짧은 글은 한 문제당 1분 이내로 빠르게 풀어요.\n  · 짧은 빈칸 문법 문제는 문맥을 보고 즉시 골라요.\n  · 광고나 안내문 문제는 찾는 정보만 빠르게 훑어봐요.\n② 긴 지문(30번 이후): 지문 전체를 처음부터 끝까지 다 읽기보다 질문과 보기를 먼저 확인하고 본문을 찾아서 읽어요.\n  · 질문의 핵심 내용이 무엇인지 먼저 확인해요.\n  · 접속사(그러나, 따라서) 뒤의 중심 문장을 먼저 살펴봐요.\n자신의 현재 실력에 맞춰 쉬운 문제를 빠짐없이 맞히는 것이 중요해요.\n\nTo manage time on the reading section, solve the first 20 questions quickly within 15-20 minutes. For longer passages (30+), read the questions and multiple choices first to know what key facts to scan for in the text.\n\n치즈감자 「TOPIK」 모의고사로 시간을 재며 풀어 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'topik', E'TOPIK 단어는 하루에 몇 개씩 어떻게 외우는 게 좋아요?', E'단어장을 사서 외우고 있는데 며칠 지나면 다 잊어버려요. 하루에 몇 개씩 외워야 효율적인가요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'TOPIK 단어는 하루에 몇 개씩 어떻게 외우는 게 좋아요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'단어만 따로 외우지 말고 문맥과 함께 짧게 자주 반복하는 것이 좋아요.\n\n① 하루 20~30개씩 가볍게 반복하기: 하루에 100개씩 외우고 잊어버리는 것보다 매일 30개를 3일 동안 반복해 마주치는 것이 오래 남아요.\n  · 아침에 단어를 보고 저녁에 퀴즈로 복습해요.\n  · 3일 뒤에 다시 확인해서 모르는 단어만 골라내요.\n② 예문과 짝단어로 외우기: 단어 단독이 아니라 자주 붙어 다니는 서술어와 함께 외워요.\n  · 「감기」만 외우지 말고 「감기에 걸리다」로 묶어서 외워요.\n  · 「약속」만 외우지 말고 「약속을 지키다 / 어기다」로 함께 공부해요.\n\nRather than memorizing 100 isolated words a day and forgetting them, review 20-30 words in collocations and short sentences every day across several days. Learning words together with their natural verbs helps long-term retention.\n\n치즈감자 「단어」에서 TOPIK 급수별 낱말을 예문과 함께 외워 보세요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'speak', E'Why is 음악이 pronounced [으마기]? Pronunciation rule for batchim?', E'I saw the word written as 음악이, but when my Korean friend said it, it sounded like 으마기. Why did the ㄱ move to the next syllable?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'Why is 음악이 pronounced [으마기]? Pronunciation rule for batchim?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'받침 뒤에 모음(ㅇ)으로 시작하는 말이 오면 소리가 넘어가는 \'연음 법칙\' 때문이에요.\n\n① 연음 규칙: 받침이 있는 글자 뒤에 조사나 어미처럼 뜻이 없는 모음(-이, -은, -을, -에)이 오면, 받침 소리가 다음 음절 첫소리로 옮겨가요.\n  · 음악이 -> [으마기]\n  · 한국어 -> [한구거]\n  · 옷을 입어요 -> [오슬 이버요]\n글자를 쓸 때는 원래 단어의 형태를 밝혀 적지만, 소리를 낼 때는 입 모양이 편하게 이어져요.\n\nWhen a syllable ending with a final consonant (batchim) is followed by a vowel starting with the silent consonant ㅇ, the batchim sound carries over to the next syllable. This is called liaison (연음). It makes speaking smoother and natural.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'speak', E'한국어 「ㅓ」와 「ㅗ」 발음이 너무 비슷하게 들려요', E'선생님이 말씀하실 때 \'서울\'과 \'소울\', \'어머니\'와 \'오머니\' 소리가 거의 비슷하게 들려요. 입 모양을 어떻게 해야 구별할 수 있나요?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'한국어 「ㅓ」와 「ㅗ」 발음이 너무 비슷하게 들려요') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'입술 모양이 둥글게 모이는지, 턱이 아래로 떨어지는지가 가장 큰 차이예요.\n\n① ㅗ [o]: 입술을 앞으로 동그랗게 모으고 혀를 뒤로 당겨 소리를 내요.\n  · 오이 [오이]\n  · 오늘 [오늘]\n② ㅓ [eo]: 입술을 동그랗게 모으지 않고, 턱을 아래로 편안하게 떨어뜨리며 입을 조금 더 벌려요.\n  · 어머니 [어머니]\n  · 서울 [서울]\n거울을 보고 입술이 둥글게 모이면 「ㅗ」, 입술에 힘을 빼고 턱이 내려가면 「ㅓ」라고 기억하면 쉽게 구별돼요.\n\nFor ㅗ [o], round your lips into a tight circle. For ㅓ [eo], relax your lips (do not round them) and drop your jaw slightly downwards. Practicing in front of a mirror helps check whether your lips form a circle.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'speak', E'Why does 감사합니다 sound like [감사함니다]?', E'The spelling clearly has ㅂ in 합, but everyone says 함니다. Is there a phonetic rule behind this?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'Why does 감사합니다 sound like [감사함니다]?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'받침 \'ㅂ\' 뒤에 \'ㄴ\'이 올 때 입 모양이 부드럽게 바뀌는 \'비음화 법칙\' 때문이에요.\n\n① 비음화: 받침 [ㄱ, ㄷ, ㅂ] 뒤에 첫소리 [ㄴ, ㅁ]이 이어지면 각각 콧소리 [ㅇ, ㄴ, ㅁ]으로 바뀌어 소리 나요.\n  · 감사합니다 -> [감사함니다]\n  · 입니다 -> [임니다]\n  · 합니다 -> [함니다]\n받침 ㅂ을 닫은 뒤 곧바로 ㄴ 소리를 내려고 하면 근육이 불편하기 때문에, 자연스럽게 입술 콧소리인 [ㅁ]으로 변해요.\n\nWhen the final consonant ㅂ meets an initial consonant ㄴ, the ㅂ assimilates into a nasal sound [ㅁ]. This nasalization (비음화) happens naturally because transitioning smoothly from ㅂ to ㄴ through the nose requires less vocal effort.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'speak', E'한국인 친구를 처음 만났을 때 어떤 말로 대화를 시작하면 좋을까요?', E'언어 교환이나 모임에서 한국인을 처음 만났을 때 어색하지 않게 스몰토크를 시작할 수 있는 첫마디가 궁금해요.' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'한국인 친구를 처음 만났을 때 어떤 말로 대화를 시작하면 좋을까요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'날씨, 오는 길, 인사말을 가볍게 건네며 대화를 열면 자연스러워요.\n\n① 기본 인사와 소개: 먼저 반갑게 인사하고 이름을 말해요.\n  · 안녕하세요! 만나서 반가워요.\n  · 저는 ○○라고 해요. (○○에 내 이름)\n② 가벼운 상황 질문: 날씨나 찾아온 길에 대해 물어보면 대화가 부드럽게 이어져요.\n  · 오늘 날씨가 참 좋지요?\n  · 여기 오는 데 길은 안 복잡했어요?\n상대의 대답을 듣고 「아, 정말요?」나 「맞아요」와 같은 짧은 맞장구를 곁들이면 훨씬 친근한 인상을 줄 수 있어요.\n\nTo break the ice when meeting someone for the first time, start with a warm greeting and brief introduction, followed by light small-talk about the weather or finding the location. Use active reactions like 아, 정말요? (Oh, really?) to keep the conversation flowing.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'life', E'How should I call a waiter at a Korean restaurant?', E'I know in some countries shouting at a waiter is rude. In Korea, how do locals politely get the staff\'s attention?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'How should I call a waiter at a Korean restaurant?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'한국 식당에서는 소리 내어 부르는 것이 일반적인 문화예요. 벨이 있으면 벨을 누르고, 없으면 적절한 호칭으로 부르면 돼요.\n\n① 여기요 / 저기요: 가장 흔하고 무난하게 부르는 표현이에요.\n  · 저기요, 여기 물 좀 더 주세요.\n  · 여기요, 주문할게요.\n② 사장님 / 이모님: 식당 주인이거나 친근한 식당에서는 「사장님」이라고 부르면 정중하고 듣는 분도 좋아해요.\n  · 사장님, 여기 메뉴판 다시 보여 주세요.\n  · 이모님, 김치 조금만 더 주실 수 있나요?\n손을 가볍게 들면서 또렷한 목소리로 부르면 직원이 친절하게 응답해요.\n\nIn Korean restaurants, calling out to staff is completely polite and standard. Look for a call button on the table first. If there isn\'t one, raise your hand slightly and say \'저기요\' (excuse me) or politely address them as \'사장님\' (boss / owner).\n\n치즈감자 「여행 한국어」의 「식당 & 카페」에서 주문 표현을 더 볼 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'life', E'한국인 친구에게 언니, 누나, 형, 오빠는 언제 부를 수 있나요?', E'친해지고 싶은 한국인에게 처음부터 언니나 오빠라고 불러도 되나요? 나이 차이가 나면 어떻게 불러야 하는지 알고 싶어요.' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'한국인 친구에게 언니, 누나, 형, 오빠는 언제 부를 수 있나요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'처음 만난 자리에서 바로 부르기보다는 나이를 확인하고 친해진 뒤에 부르는 것이 자연스러워요.\n\n① 호칭 정리의 기준: 상대가 나보다 나이가 많을 때 여자는 언니·오빠, 남자는 누나·형으로 불러요.\n② 자연스럽게 묻고 부르기: 처음에는 「이름 + 씨」로 부르다가, 나이를 확인한 뒤 상대방에게 조심스럽게 허락을 구해요.\n  · 제가 편하게 형이라고 불러도 돼요?\n  · 앞으로 저한테 말 편하게 하셔도 돼요.\n상대방이 동의했을 때 호칭을 바꾸면 훨씬 친밀해져요.\n\nTitles like 언니, 오빠, 형, and 누나 depend on both your gender and the other person\'s gender. Do not use them immediately on the first meeting. Start with \'Name + 씨\', and once you know their age and build rapport, politely ask if you may use these friendly titles.\n\n치즈감자 「단어」의 「관계 · 호칭」 주제에서 호칭 낱말을 볼 수 있어요.' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'life', E'What do \'ㅋㅋ\' and \'ㅎㅎ\' mean in Korean text messages?', E'My Korean friends frequently send messages ending with ㅋㅋㅋ or ㅎㅎㅎ. Are there different nuances between them?' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'What do \'ㅋㅋ\' and \'ㅎㅎ\' mean in Korean text messages?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'모바일 채팅에서 웃는 소리를 자음만으로 줄여 쓴 표현이에요.\n\n① ㅋㅋ: \'크크\' 또는 \'키키\' 웃는 소리예요. 가볍고 솔직하게 웃길 때 가장 많이 써요. 개수가 많을수록 더 크게 웃는 느낌을 줘요.\n  · 진짜 웃기다 ㅋㅋㅋㅋ\n  · 내일 늦지 마 ㅋㅋ\n  (단, \'ㅋ\'을 하나만 쓰면 비웃거나 차가워 보일 수 있으니 두 개 이상 쓰는 것이 좋아요.)\n② ㅎㅎ: \'하하\' 또는 \'헤헤\' 웃는 소리예요. 부드럽고 다정하며 공손한 웃음을 나타내요.\n  · 네, 알겠습니다 ㅎㅎ\n  · 오늘 정말 즐거웠어요 ㅎㅎㅎ\n상황에 맞추어 친구에게는 \'ㅋㅋ\'를, 조금 더 예의를 갖추고 싶을 때는 \'ㅎㅎ\'를 쓰면 돼요.\n\nIn Korean chat, ㅋㅋ represents a burst of laughter (like lol or haha). Using just one \'ㅋ\' can seem cynical, so locals usually type at least two. ㅎㅎ represents a gentler, softer, more polite smile or chuckle (like hehe or a friendly smile).' from q;
with q as (insert into qa_questions (user_id, author, board, title, body) select (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '자주 묻는 질문', 'life', E'편의점이나 카페에서 직원이 물어볼 때 뭐라고 대답해야 하나요?', E'편의점이나 카페에 가면 직원이 \'봉투 필요하세요?\'나 \'드시고 가세요?\'라고 빠르게 물어봐서 당황해요. 짧고 자연스러운 대답을 알려주세요.' where (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1) is not null and not exists (select 1 from qa_questions where title = E'편의점이나 카페에서 직원이 물어볼 때 뭐라고 대답해야 하나요?') returning id) insert into qa_answers (question_id, user_id, author, body) select q.id, (select id from auth.users where email = 'junsanghan1225@gmail.com' limit 1), '치즈감자', E'자주 묻는 질문 몇 가지만 기억해 두면 쉽게 대답할 수 있어요.\n\n① 봉투 필요하세요?: 필요하면 \'네, 주세요\', 필요 없으면 \'아니요, 괜찮아요\'라고 해요.\n  · 봉투 요청: 네, 종이봉투 하나 주세요.\n② 드시고 가세요? / 포장이세요?: 매장에서 먹을 때는 \'먹고 갈게요\', 밖으로 가져갈 때는 \'가져갈게요\'나 \'포장해 주세요\'라고 해요.\n  · 포장 여부: 먹고 갈게요. / 가져갈게요.\n③ 영수증 드릴까요?: \'네, 주세요\' 또는 \'버려 주세요(괜찮아요)\'라고 답하면 돼요.\n  · 영수증 처리: 영수증은 버려 주세요.\n\nAt convenience stores and cafes, staff frequently ask about bags, receipts, and dining in. For bags: 네, 주세요 (Yes, please) or 아니요, 괜찮아요 (No, I am fine). For dining in: 먹고 갈게요 (Eating here) or 포장해 주세요 (To go).\n\n치즈감자 「여행 한국어」의 「식당 & 카페」에서 매장 표현을 더 볼 수 있어요.' from q;
alter table qa_questions enable trigger qa_limit;
commit;
select (select count(*) from qa_questions where author = '자주 묻는 질문') as 질문, (select count(*) from qa_answers a join qa_questions q on q.id = a.question_id where q.author = '자주 묻는 질문') as 답;
